import React, { useState } from 'react';
import { projectAPI } from '../../services/api';

const CreateProject = ({ onProjectCreated, onCancel, onError }) => {
  const [formData, setFormData] = useState({ 
    name: '', 
    description: '',
    team_id: '' 
  });
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!formData.name.trim()) {
      onError('Project name is required');
      return;
    }

    setLoading(true);
    onError('');

    try {
      console.log('Creating project with data:', formData);
      const response = await projectAPI.create(formData);
      console.log('Project created successfully:', response.data);
      onProjectCreated(response.data.project);
      setFormData({ name: '', description: '', team_id: '' });
    } catch (error) {
      console.error('Project creation error:', error);
      const errorMessage = error.response?.data?.error || 'Failed to create project';
      onError(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="create-project-form">
      <h3>Create New Project</h3>
      
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label>Project Name *</label>
          <input
            type="text"
            name="name"
            value={formData.name}
            onChange={handleChange}
            required
            placeholder="Enter project name"
            disabled={loading}
            style={{width: '100%', padding: '0.75rem', marginBottom: '1rem', border: '1px solid #ddd', borderRadius: '5px'}}
          />
        </div>

        <div className="form-group">
          <label>Description</label>
          <textarea
            name="description"
            value={formData.description}
            onChange={handleChange}
            placeholder="Describe your project (optional)"
            rows="3"
            disabled={loading}
            style={{width: '100%', padding: '0.75rem', marginBottom: '1rem', border: '1px solid #ddd', borderRadius: '5px', fontFamily: 'inherit'}}
          />
        </div>

        <div className="form-group">
          <label>Team (Optional)</label>
          <select
            name="team_id"
            value={formData.team_id}
            onChange={handleChange}
            disabled={loading}
            style={{width: '100%', padding: '0.75rem', marginBottom: '1rem', border: '1px solid #ddd', borderRadius: '5px'}}
          >
            <option value="">Personal Project</option>
            {/* Teams will be populated later */}
          </select>
        </div>

        <div className="form-actions">
          <button 
            type="button" 
            className="btn btn-secondary"
            onClick={onCancel}
            disabled={loading}
            style={{marginRight: '1rem'}}
          >
            Cancel
          </button>
          <button 
            type="submit" 
            className="btn btn-primary"
            disabled={loading}
          >
            {loading ? 'Creating...' : 'Create Project'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default CreateProject;
